/**
 * Built-in preset avatars.
 *
 * These are bundled in `public/avatars/` (generated by
 * `scripts/make-avatars.mjs`) rather than fetched from an avatar service.
 *
 * That is a deliberate change: the previous source, i.pravatar.cc, began
 * answering **403 to every request**, so 22 of the 24 presets rendered as broken
 * images. Local files always load, work offline, and cost under a kilobyte each.
 */

export const PRESET_AVATAR_COUNT = 12;

export const PRESET_AVATARS: string[] = Array.from(
  { length: PRESET_AVATAR_COUNT },
  (_, index) => `/avatars/avatar-${index + 1}.svg`,
);

/**
 * Deterministically pick a preset for a seed (an email or user id), so the same
 * account always gets the same default avatar instead of one that changes on
 * every login.
 */
export function presetAvatarFor(seed: string): string {
  let hash = 2166136261;
  for (let index = 0; index < seed.length; index++) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return PRESET_AVATARS[(hash >>> 0) % PRESET_AVATAR_COUNT];
}
